		function reloadRoleSkills(): void {
			const match = editor.value.match(/^skills:\s*(.+)$/m);
			if (match) {
				roleSelectedSkills = match[1]!
					.split(",")
					.map((s) => s.trim())
					.filter(Boolean);
			} else {
				roleSelectedSkills = [];
			}
			renderRoleSkillChips();
