			const yaml = roleSelectedSkills.length > 0 ? `skills: ${roleSelectedSkills.join(", ")}` : "skills: ";
			if (/^skills:/m.test(editor.value)) {
				editor.value = editor.value.replace(/^skills:.*$/m, yaml);
			} else {
				editor.value = editor.value.replace(/^---\n/, `---\n${yaml}\n`);
