/* === Role Sub-Rows (in room list) === */

.room-role-sub-rows {
  margin-top: 0.2rem;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  padding-left: 0.85rem;
}

.room-role-sub-row {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  width: 100%;
  text-align: left;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface-subtle);
  padding: 0.35rem 0.65rem;
  cursor: default;
  font: inherit;
  font-size: 0.75rem;
  color: var(--text-body);
  transition:
    border-color var(--duration-fast),
    background var(--duration-fast);
}

.room-role-sub-row.clickable {
  cursor: pointer;
}

.room-role-sub-row.clickable:hover {
  border-color: var(--accent-100);
  background: var(--accent-50);
}

.role-sub-dot {
  flex-shrink: 0;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--muted);
}

